private lemma f2_sum_add {a b : ℕ} (f : Fin (a + b) → ℕ) :
    (∑ i : Fin (a + b), f i) =
      (∑ i : Fin a, f (Fin.castAdd b i)) + ∑ i : Fin b, f (Fin.natAdd a i)

private def f2_condHeads (D M₁ M₂ : FinTM Bool) (d : Fin D.k → ℤ)
    (b : Fin (M₁.k + M₂.k) → ℤ) (z : ℤ) :
    Fin ((D.k + (M₁.k + M₂.k)) + 1) → ℤ

private lemma a2_heads_mono {k : ℕ} {Q : Type} {x : List Bool}
    {c : Cfg k Bool Q x} {A B : ℕ} (h : a2_heads c A) (hle : A ≤ B) :
    a2_heads c B

private lemma a2_heads_steps {k : ℕ} {Q : Type} {x : List Bool}
    (tm : MultiTapeTM k Bool Q) (c : Cfg k Bool Q x) (A B t : ℕ)
    (h : a2_heads c A) (ht : t ≤ B) : a2_heads (tm.runFrom c t) (A + B)

theorem step_of_inputMoveAction {Symbol State : Type*} {k : ℕ} {x : List Symbol}
    (M : MultiTapeTM k Symbol State) (c : Cfg k Symbol State x) {q q' : State}
    (inp : SignType) (hq : c.state = some q)
    (htr : M.tr q c.inputSymbol c.workTapeSymbols = inputMoveAction inp q') :
    M.step c = { c with state := some q', inputPos := moveInputPos c.inputPos inp }

