private def canonStageBank {x : List Bool} (M : ℕ) (header ctrOuter : Fin M) {S' : Type}
    (q : Option S') (ip : Fin (x.length + 2)) (ct : ℤ → Option Bool) (cp : ℤ)
    (w : List Bool) : Cfg M Bool S' x

