    (P : MultiTapeTM (m₃ + 2) Bool H₃) (anchor₃ : H₃) (ι₃ : Fin (m₃ + 2) ↪ Fin M) :
    (i : Fin 4) → MultiTapeTM M Bool (canonGramPh HF H₃ i)

