    codeSkipRepeat r (n + 1) xs = (codeSkipRepeat r n xs).bind r

private lemma canonStageBlock_consumes (k n : ℕ) (xs ys : List Bool)
    (h : codeSkipRepeat (codeSkipActionK k n) (3 ^ (k + 1)) xs = some ys) :
